# Searches this database's records by name or meaning.
RECORD = {
    "id": "JAH-NMY-000001",
    "name": "Adeyemi",
    "kind": "first-name",
    "meaning": "Adeyemi is a masculine given name in Yoruba. Meaning: The crown befits me. Ade (crown) + yemi (befits me)."
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Ade")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

